# derive a broad set of binary object features and find exact linear parity rules over the demonstrations
import itertools
features={}
for key in ['color','y','x','n','h','w','ysum','xsum','xy_sum']:
    features[key]=df[key].astype(int).to_numpy()%2
# shape coordinate invariants within bounding box
shape_feats={}
for o in demos:
    pts=o['pts']; rr=[p[0] for p in pts]; cc=[p[1] for p in pts]; r0=min(rr); c0=min(cc); h=max(rr)-r0+1; w=max(cc)-c0+1; n=len(pts)
    local={(r-r0,c-c0) for r,c in pts}
    counts_r=[sum(r==i for r,c in local) for i in range(h)]
    counts_c=[sum(c==i for r,c in local) for j in []] if False else [sum(c==i for r,c in local) for i in range(w)]
    vals={
        'local_checker':sum((r+c)%2 for r,c in local)%2,
        'checker_global':sum((r+c)%2 for r,c in pts)%2,
        'toprow':counts_r[0]%2,'bottomrow':counts_r[-1]%2,
        'leftcol':counts_c[0]%2,'rightcol':counts_c[-1]%2,
        'rowcount_sum_sq':sum(q*q for q in counts_r)%2,
        'colcount_sum_sq':sum(q*q for q in counts_c)%2,
        'holes':0,
        'row_extreme_diff':(counts_r[0]-counts_r[-1])%2,
        'n_minus_area':(n-h*w)%2,
    }
    # enclosed 4-neighbor holes within bbox
    zeros={(r,c) for r in range(h) for c in range(w)}-local
    # flood from boundary zeros
    seen=set(); stack=[z for z in zeros if z[0] in (0,h-1) or z[1] in (0,w-1)]
    while stack:
        p=stack.pop()
        if p in seen or p not in zeros: continue
        seen.add(p)
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)): stack.append((p[0]+dr,p[1]+dc))
    vals['holes']=len(zeros-seen)%2
    for k,v in vals.items(): shape_feats.setdefault(k,[]).append(v)
features.update({k:np.array(v,dtype=int) for k,v in shape_feats.items()})
y=(df['dest']=='down').astype(int).to_numpy()
# see direct/ pair parity feature matches
matches=[]
for k,v in features.items():
    if np.array_equal(v,y): matches.append((k,))
    if np.array_equal(1-v,y): matches.append(('not '+k,))
for a,b in itertools.combinations(features,2):
    if np.array_equal(features[a]^features[b],y): matches.append((a,'xor',b))
print('matches',matches)
print('features', list(features))

# Enrich object morphology metrics for pattern inspection
from collections import deque
mor=[]
for o in demos:
    pts=o['pts']; r0=min(r for r,c in pts); c0=min(c for r,c in pts); rr=[r for r,c in pts]; cc=[c for r,c in pts]; h=max(rr)-r0+1; w=max(cc)-c0+1
    s={(r-r0,c-c0) for r,c in pts}
    # 4-connected components
    unseen=set(s); comps=[]
    while unseen:
        st=[unseen.pop()]; comp=set(st)
        while st:
            r,c=st.pop()
            for q in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                if q in unseen: unseen.remove(q);comp.add(q);st.append(q)
        comps.append(comp)
    # symmetry
    def image(kind):
        if kind=='h': return {(h-1-r,c) for r,c in s}
        if kind=='v': return {(r,w-1-c) for r,c in s}
        if kind=='180': return {(h-1-r,w-1-c) for r,c in s}
        if kind=='diag' and h==w:return {(c,r) for r,c in s}
        return set()
    sym={k:int(image(k)==s) for k in ['h','v','180','diag']}
    # degree stats, perimeter, fill ratio
    deg=[sum(q in s for q in ((r+1,c),(r-1,c),(r,c+1),(r,c-1))) for r,c in s]
    rowcounts=[sum(r==i for r,c in s) for i in range(h)]
    colcounts=[sum(c==i for r,c in s) for i in range(w)]
    mor.append(dict(name=o['name'],dest=o['dest'],n=len(s),hw=f'{h}x{w}',h=h,w=w,holes=features['holes'][len(mor)] if False else 0,
        comp4=len(comps),maxdeg=max(deg),mindeg=min(deg),edges=sum(deg)//2,perimeter=4*len(s)-2*sum(deg)//2,
        symh=sym['h'],symv=sym['v'],sym180=sym['180'],rowcounts=str(rowcounts),colcounts=str(colcounts),
        singletons=sum(d==0 for d in deg),endpoints=sum(d==1 for d in deg),branch=sum(d>=3 for d in deg)))
mordf=pd.DataFrame(mor)
mordf

